        "css": "body {\n  margin: 0;\n  background-color: #f8fafc;\n  color: #0f172a;\n  font-family: system-ui, sans-serif;\n}\n\n.page {\n  display: grid;\n  justify-items: center;\n  gap: 1rem;\n  max-width: 28rem;\n  margin: 0 auto;\n  padding: 2rem 1rem 3rem;\n  text-align: center;\n}\n\n.spinner {\n  width: 2.5rem;\n  height: 2.5rem;\n  border: 4px solid #c7d2fe;\n  border-top-color: #4f46e5;\n  border-radius: 50%;\n  animation-name: spin;\n  animation-duration: 1s;\n  animation-timing-function: linear;\n  animation-iteration-count: infinite;\n}\n\n.title {\n  margin: 0;\n  font-size: 2rem;\n  animation-name: rise;\n  animation-duration: 0.6s;\n  animation-fill-mode: both;\n}\n\n.tagline {\n  margin: 0;\n  color: #475569;\n  animation-name: rise;\n  animation-duration: 0.6s;\n  animation-delay: 0.2s;\n  animation-fill-mode: both;\n}\n\n.list {\n  display: grid;\n  gap: 0.5rem;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.item {\n  padding: 0.6rem 1.5rem;\n  border-radius: 0.5rem;\n  background-color: #e0e7ff;\n}\n\n.flip {\n  width: 12rem;\n  height: 6rem;\n}\n\n.flip-inner {\n  position: relative;\n  width: 100%;\n  height: 100%;\n}\n\n.front,\n.back {\n  position: absolute;\n  inset: 0;\n  display: grid;\n  place-items: center;\n  border-radius: 0.75rem;\n  color: #ffffff;\n  font-weight: 700;\n}\n\n.front {\n  background-color: #4f46e5;\n}\n\n.back {\n  background-color: #0f766e;\n}\n\n.cta {\n  padding: 0.7rem 1.4rem;\n  border: 0;\n  border-radius: 0.5rem;\n  background-color: #4f46e5;\n  color: #ffffff;\n  font: inherit;\n  font-weight: 600;\n}\n\n@keyframes spin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n@keyframes rise {\n  from {\n    opacity: 0;\n    transform: translateY(12px);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}"
